  var MESES = { janeiro: ['January', 'enero'], fevereiro: ['February', 'febrero'], 'março': ['March', 'marzo'], abril: ['April', 'abril'], maio: ['May', 'mayo'], junho: ['June', 'junio'], julho: ['July', 'julio'], agosto: ['August', 'agosto'], setembro: ['September', 'septiembre'], outubro: ['October', 'octubre'], novembro: ['November', 'noviembre'], dezembro: ['December', 'diciembre'] };

